//! Mock embedding backend for testing.
//!
//! Provides deterministic embeddings based on text hash for reproducible tests.

use rag_core::{EmbeddingBackend, EmbeddingError};
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

/// A mock embedding backend that returns deterministic embeddings.
///
/// Embeddings are generated by hashing character n-grams of the input text, ensuring:
/// - Same text always produces the same embedding
/// - Similar texts produce correlated embeddings (unlike pure random hashing)
/// - Embeddings are normalized (unit length)
pub struct MockEmbeddingBackend {
    dimension: usize,
    model_id: String,
}

impl MockEmbeddingBackend {
    /// Create a new mock backend with specified dimension.
    pub fn new(dimension: usize) -> Self {
        Self {
            dimension,
            model_id: format!("mock-{}", dimension),
        }
    }

    /// Generate deterministic embedding from text n-grams.
    fn hash_to_embedding(&self, text: &str) -> Vec<f32> {
        let mut embedding = vec![0.0; self.dimension];

        // Character n-gram hashing (n=3)
        // Fallback to simpler hashing for very short strings
        let chars: Vec<char> = text.chars().collect();
        let n = 3;

        if chars.len() < n {
            // Handle short strings by hashing the whole string to one index
            let mut hasher = DefaultHasher::new();
            text.hash(&mut hasher);
            let hash = hasher.finish();
            let idx = (hash as usize) % self.dimension;
            embedding[idx] += 1.0;
        } else {
            for window in chars.windows(n) {
                let mut hasher = DefaultHasher::new();
                window.hash(&mut hasher);
                let hash = hasher.finish();
                let idx = (hash as usize) % self.dimension;
                embedding[idx] += 1.0;
            }
        }

        // Normalize to unit length
        let norm: f32 = embedding.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            for x in &mut embedding {
                *x /= norm;
            }
        }

        embedding
    }
}

impl EmbeddingBackend for MockEmbeddingBackend {
    fn model_id(&self) -> &str {
        &self.model_id
    }

    fn dimension(&self) -> usize {
        self.dimension
    }

    fn embed(
        &self,
        text: &str,
    ) -> impl std::future::Future<Output = Result<Vec<f32>, EmbeddingError>> + Send {
        let embedding = self.hash_to_embedding(text);
        async move { Ok(embedding) }
    }

    fn embed_batch(
        &self,
        texts: &[String],
    ) -> impl std::future::Future<Output = Result<Vec<Vec<f32>>, EmbeddingError>> + Send {
        let embeddings: Vec<Vec<f32>> = texts.iter().map(|t| self.hash_to_embedding(t)).collect();
        async move { Ok(embeddings) }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_deterministic_embeddings() {
        let backend = MockEmbeddingBackend::new(384);

        // Same text should produce same embedding
        let emb1 = backend.hash_to_embedding("hello world");
        let emb2 = backend.hash_to_embedding("hello world");
        assert_eq!(emb1, emb2);

        // Different text should produce different embedding
        let emb3 = backend.hash_to_embedding("goodbye world");
        assert_ne!(emb1, emb3);
    }

    #[test]
    fn test_correct_dimension() {
        let backend = MockEmbeddingBackend::new(768);
        let emb = backend.hash_to_embedding("test");
        assert_eq!(emb.len(), 768);
    }

    #[test]
    fn test_normalized() {
        let backend = MockEmbeddingBackend::new(384);
        let emb = backend.hash_to_embedding("test");

        let norm: f32 = emb.iter().map(|x| x * x).sum::<f32>().sqrt();
        assert!((norm - 1.0).abs() < 0.001, "Expected unit norm, got {}", norm);
    }

    #[test]
    fn test_model_id() {
        let backend = MockEmbeddingBackend::new(384);
        assert_eq!(backend.model_id(), "mock-384");
    }

    #[test]
    fn test_semantic_similarity() {
        let backend = MockEmbeddingBackend::new(384);

        let base = backend.hash_to_embedding("hello world");
        let similar = backend.hash_to_embedding("hello");
        let different = backend.hash_to_embedding("pizza");

        let dot_product = |a: &[f32], b: &[f32]| -> f32 {
            a.iter().zip(b).map(|(x, y)| x * y).sum()
        };

        let sim_similar = dot_product(&base, &similar);
        let sim_different = dot_product(&base, &different);

        assert!(
            sim_similar > sim_different,
            "Expected 'hello' ({:.4}) to be more similar to 'hello world' than 'pizza' ({:.4})",
            sim_similar,
            sim_different
        );
    }
}
